"""Command and produced-artifact checks for Linux tasks.

The evaluator runs the command a task declares, compares its exit status and
its standard output with the declared values, and reads the trajectory file
that the run produced.  The trajectory is treated strictly as a produced
artifact: only its presence and its declared minimum entry count are read, and
the order or content of its entries is never judged.  A missing artifact is a
failed task.
"""

from __future__ import annotations

import json
import os
from collections.abc import Mapping
from pathlib import Path
from typing import Any

from evaluators.cua_review.core.evaluation import BaseEvaluator, EvalResult, EvalStatus
from evaluators.cua_review.evaluators.linux.command_check import run_command

DEFAULT_TIMEOUT = 60


def _expand(raw: Any) -> str:
    return str(Path(os.path.expandvars(os.path.expanduser(str(raw)))))


def _trajectory_candidates(context: Mapping[str, Any], params: Mapping[str, Any]) -> list[str]:
    raw: list[str] = []
    for name in ("trajectory_path", "trajectory"):
        value = params.get(name)
        if isinstance(value, str) and value:
            raw.append(value)
        elif isinstance(value, Mapping):
            for key in ("path", "file", "trajectory_path"):
                if value.get(key):
                    raw.append(str(value[key]))
    direct = context.get("trajectory_path")
    if isinstance(direct, str) and direct:
        raw.append(direct)
    run_dir = context.get("run_dir")
    if run_dir:
        raw.append(os.path.join(str(run_dir), "trajectory.jsonl"))
        raw.append(os.path.join(str(run_dir), "trajectory.json"))
    found: list[str] = []
    for item in raw:
        path = _expand(item)
        if path not in found:
            found.append(path)
    return found


def _count_entries(path: str) -> int | None:
    try:
        with open(path, encoding="utf-8", errors="replace") as stream:
            text = stream.read()
    except OSError:
        return None
    stripped = text.strip()
    if not stripped:
        return 0
    if path.endswith(".json") or stripped[:1] in "[{":
        try:
            parsed = json.loads(stripped)
        except ValueError:
            parsed = None
        if isinstance(parsed, list):
            return len(parsed)
        if isinstance(parsed, Mapping) and isinstance(parsed.get("steps"), list):
            return len(parsed["steps"])
    return sum(1 for line in text.splitlines() if line.strip())


class CommandAndTrajectoryEvaluator(BaseEvaluator):
    """Run the declared command and read the produced trajectory artifact."""

    def evaluate(self, context: Mapping[str, Any]) -> EvalResult:
        params = dict(context.get("params") or {})
        timeout = int(params.get("timeout", DEFAULT_TIMEOUT) or DEFAULT_TIMEOUT)
        checks: list[dict[str, Any]] = []
        failures: list[str] = []

        command = str(params.get("command") or "")
        if command.strip():
            outcome = run_command(context.get("controller"), command, timeout)
            if outcome is None:
                return EvalResult(
                    status=EvalStatus.FAIL,
                    message="the declared command could not be run",
                    metadata={"checks": checks, "failures": ["command_transport"]},
                )
            try:
                expected_code = int(params.get("expected_exit_code", 0))
            except (TypeError, ValueError):
                expected_code = 0
            code_ok = int(outcome["returncode"]) == expected_code
            checks.append(
                {
                    "check": "exit_code",
                    "expected": expected_code,
                    "observed": outcome["returncode"],
                    "passed": code_ok,
                }
            )
            if not code_ok:
                failures.append("exit_code")
            marker = params.get("stdout_contains")
            if marker is not None:
                marker_ok = str(marker) in str(outcome["stdout"])
                checks.append(
                    {
                        "check": "stdout_contains",
                        "expected": str(marker),
                        "observed": str(outcome["stdout"])[-2000:],
                        "passed": marker_ok,
                    }
                )
                if not marker_ok:
                    failures.append("stdout_contains")

        wanted_files: list[str] = []
        single = params.get("artifact_path")
        if isinstance(single, str) and single:
            wanted_files.append(single)
        for item in params.get("artifact_paths") or params.get("expected_files") or []:
            if item:
                wanted_files.append(str(item))
        minimum_bytes = params.get("min_bytes")
        for raw_path in wanted_files:
            path = _expand(raw_path)
            size = os.path.getsize(path) if os.path.isfile(path) else None
            passed = size is not None and (
                minimum_bytes is None or size >= int(minimum_bytes)
            )
            checks.append(
                {
                    "check": "artifact:" + raw_path,
                    "expected": {"present": True, "min_bytes": minimum_bytes},
                    "observed": {"size": size},
                    "passed": passed,
                }
            )
            if not passed:
                failures.append("artifact:" + raw_path)

        if params.get("min_steps") is not None:
            minimum_steps = int(params.get("min_steps") or 0)
            candidates = _trajectory_candidates(context, params)
            present = [path for path in candidates if os.path.isfile(path)]
            if not present:
                checks.append(
                    {
                        "check": "trajectory",
                        "expected": {"present": True, "min_steps": minimum_steps},
                        "observed": {"searched": candidates},
                        "passed": False,
                    }
                )
                failures.append("trajectory")
            else:
                counts = {path: _count_entries(path) for path in present}
                passed = any(
                    count is not None and count >= minimum_steps for count in counts.values()
                )
                checks.append(
                    {
                        "check": "trajectory",
                        "expected": {"present": True, "min_steps": minimum_steps},
                        "observed": counts,
                        "passed": passed,
                    }
                )
                if not passed:
                    failures.append("trajectory")

        if not checks:
            return EvalResult(
                status=EvalStatus.FAIL,
                message="the task declares neither a command nor an artifact",
                metadata={"checks": checks, "failures": ["no_declared_outcome"]},
            )

        passed = not failures
        return EvalResult(
            status=EvalStatus.PASS if passed else EvalStatus.FAIL,
            message=(
                "the declared command and trajectory artifact are present"
                if passed
                else "the declared outcome is not satisfied: " + ", ".join(failures)
            ),
            metadata={"checks": checks, "failures": failures},
        )


__all__ = ["CommandAndTrajectoryEvaluator"]
